package com.fireplatform.alarm;

import com.fasterxml.jackson.databind.*;
import com.fireplatform.configuration.*;
import com.fireplatform.identity.*;
import com.fireplatform.shared.ApiError;
import jakarta.websocket.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import org.junit.jupiter.api.*;
import org.springframework.test.util.ReflectionTestUtils;
import org.springframework.web.socket.*;
import org.springframework.web.socket.adapter.standard.StandardWebSocketSession;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.*;

class AlarmChangeChannelRuntimeTest {
    final AlarmChangeChannelPolicy policy=AlarmChangeChannelStateTest.policy("POLL_MS","50","SEND_TIMEOUT_MS","500","SILENCE_TIMEOUT_MS","2000");
    final AlarmChangeChannelTickets registry=new AlarmChangeChannelTickets(policy);final AlarmChangeChannelHead heads=mock(AlarmChangeChannelHead.class);final ChannelScopeAuthorization authority=mock(ChannelScopeAuthorization.class);final ObjectMapper json=new ObjectMapper();
    final RuntimeConfig config=mock(RuntimeConfig.class);AlarmChangeChannelRuntime runtime;final List<Fake> sockets=new ArrayList<>();
    @BeforeEach void start(){when(config.alarmChangeReadEnabled()).thenReturn(true);when(heads.read(anyString(),anyString())).thenReturn(new AlarmChangeChannelHead.Head(null,0));var identity=mock(AuthService.Identity.class);when(identity.tokenHash()).thenReturn(AlarmChangeChannelStateTest.HASH);when(identity.user()).thenReturn(new AuthService.UserView("bootstrap-admin","admin","Admin","PLATFORM",null,false));when(authority.require(anyString(),anyString(),anyString())).thenReturn(identity);runtime=new AlarmChangeChannelRuntime(registry,heads,authority,policy,config,json);runtime.start();}
    @AfterEach void stop(){for(var socket:sockets)runtime.closed(socket.socket);runtime.stop();}
    final class Fake {
        final org.apache.tomcat.websocket.WsSession nativeSession=mock(org.apache.tomcat.websocket.WsSession.class);final RemoteEndpoint.Async remote=mock(RemoteEndpoint.Async.class);final List<String> frames=new CopyOnWriteArrayList<>();final List<SendHandler> completions=new CopyOnWriteArrayList<>();final CountDownLatch sent=new CountDownLatch(1),closed=new CountDownLatch(1);final AtomicReference<CloseReason> reason=new AtomicReference<>();final StandardWebSocketSession socket;final AlarmChangeChannelTickets.Lease lease;
        Fake(boolean complete)throws Exception{var issue=registry.issue(AlarmChangeChannelStateTest.HASH,"tenant-a","management",AlarmChangeChannelStateTest.ORIGIN,"bootstrap-admin");lease=registry.claim(issue.ticket(),AlarmChangeChannelStateTest.ORIGIN,"management");when(nativeSession.getAsyncRemote()).thenReturn(remote);when(nativeSession.getUserProperties()).thenReturn(new HashMap<>());when(nativeSession.getRequestURI()).thenReturn(java.net.URI.create("ws://channel.test/api/management/alerts"));when(nativeSession.getNegotiatedSubprotocol()).thenReturn(AlarmChangeChannelHandshake.PROTOCOL);when(nativeSession.getNegotiatedExtensions()).thenReturn(List.of());when(nativeSession.isOpen()).thenReturn(true);
            socket=new StandardWebSocketSession(null,new HashMap<>(Map.of(AlarmChangeChannelHandshake.LEASE,lease)),null,null);socket.initializeNativeSession(nativeSession);
            doAnswer(invocation->{String text=invocation.getArgument(0);SendHandler completion=invocation.getArgument(1);frames.add(text);completions.add(completion);sent.countDown();if(complete)completion.onResult(new SendResult());return null;}).when(remote).sendText(anyString(),any(SendHandler.class));
            doAnswer(invocation->{reason.set(invocation.getArgument(0));closed.countDown();return null;}).when(nativeSession).close(any(CloseReason.class));sockets.add(this);
        }
        void open(){runtime.open(socket);}void awaitSend()throws Exception{assertThat(sent.await(3,TimeUnit.SECONDS)).isTrue();}void awaitClose()throws Exception{assertThat(closed.await(3,TimeUnit.SECONDS)).isTrue();}
    }
    @Test void uniformNativeAsyncFrameIsExactlyFourFieldsAndSnapshotReturnsBeforeFreshAuthority()throws Exception{String stream=UUID.randomUUID().toString();when(heads.read("bootstrap-admin","tenant-a")).thenReturn(new AlarmChangeChannelHead.Head(stream,Long.MAX_VALUE));var socket=new Fake(false);socket.open();socket.awaitSend();var frame=json.readTree(socket.frames.getFirst());assertThat(frame.size()).isEqualTo(4);assertThat(frame.get("v").intValue()).isEqualTo(1);assertThat(frame.get("type").asText()).isEqualTo("ALARM_CHANGE_SIGNAL");assertThat(frame.get("semantics").size()).isEqualTo(3);assertThat(frame.at("/semantics/delivery").asText()).isEqualTo("PER_CONNECTION_SAMPLE");assertThat(frame.at("/semantics/publisher_liveness").asText()).isEqualTo("UNCONFIRMED");assertThat(AlarmChangeCursor.decode(frame.get("head_cursor").asText()).sequence()).isEqualTo(Long.MAX_VALUE);assertThat(socket.frames.getFirst()).doesNotContain("tenant_name","alarm_id","pending_count","actor");var ordered=inOrder(heads,authority);ordered.verify(heads).read("bootstrap-admin","tenant-a");ordered.verify(authority).require(AlarmChangeChannelStateTest.HASH,"management","tenant-a");verify(socket.remote).setSendTimeout(500);}
    @Test void heldSendDoesNotQueueMoreFramesAndAnotherConnectionMakesProgress()throws Exception{var slow=new Fake(false);slow.open();slow.awaitSend();var fast=new Fake(true);var repeated=new CountDownLatch(3);doAnswer(i->{fast.frames.add(i.getArgument(0));repeated.countDown();((SendHandler)i.getArgument(1)).onResult(new SendResult());return null;}).when(fast.remote).sendText(anyString(),any(SendHandler.class));fast.open();assertThat(repeated.await(3,TimeUnit.SECONDS)).isTrue();assertThat(slow.frames).hasSize(1);assertThat(fast.frames.size()).isGreaterThanOrEqualTo(3);}
    @Test void authorityLossBetweenHeadReadAndSendProducesOnlyExactAuthorizationClose()throws Exception{when(authority.require(anyString(),anyString(),anyString())).thenThrow(new ApiError(403,"PERMISSION_DENIED","not sent"));var socket=new Fake(false);socket.open();socket.awaitClose();assertThat(socket.frames).isEmpty();assertThat(socket.reason.get().getCloseCode().getCode()).isEqualTo(1008);assertThat(socket.reason.get().getReasonPhrase()).isEqualTo("AUTHORIZATION_CHANGED");assertThat(registry.used()).isEqualTo(1);runtime.closed(socket.socket);assertThat(registry.used()).isZero();}
    @Test void headSqlFailureNeverUsesAuthorityReasonAndNeverSendsOldFrame()throws Exception{when(heads.read(anyString(),anyString())).thenThrow(new org.springframework.dao.DataAccessResourceFailureException("private SQL not exposed"));var socket=new Fake(false);socket.open();socket.awaitClose();assertThat(socket.frames).isEmpty();assertThat(socket.reason.get().getReasonPhrase()).isEqualTo("CHANNEL_UNAVAILABLE");assertThat(socket.reason.get().getCloseCode().getCode()).isEqualTo(1011);verifyNoInteractions(authority);}
    @Test void completionFailureClosesButKeepsPermitUntilContainerClosedAndLateCallbackCannotAffectNewLease()throws Exception{var old=new Fake(false);old.open();old.awaitSend();old.completions.getFirst().onResult(new SendResult(new IllegalStateException("private transport diagnostic")));old.awaitClose();assertThat(registry.used()).isEqualTo(1);runtime.closed(old.socket);var current=new Fake(false);current.open();current.awaitSend();old.completions.getFirst().onResult(new SendResult(new IllegalStateException()));assertThat(registry.used()).isEqualTo(1);assertThat(current.lease.state()).isEqualTo(AlarmChangeChannelTickets.State.ACTIVE);assertThat(current.closed.getCount()).isEqualTo(1);}
    @Test void textAndBinaryAreNotApplicationProtocolsAndNeverUseAuthorizationClose()throws Exception{for(int size:List.of(1,policy.maxMessageBytes()+1)){var socket=new Fake(false);socket.open();socket.awaitSend();runtime.protocol(socket.socket,size);socket.awaitClose();assertThat(socket.reason.get().getReasonPhrase()).isEqualTo(size==1?"PROTOCOL_INVALID":"MESSAGE_TOO_LARGE");assertThat(socket.reason.get().getCloseCode().getCode()).isEqualTo(size==1?1008:1009);runtime.closed(socket.socket);}}
    @Test void fullWorkerQueueRetriesClosingWithoutTimerIoAndRetainsFirstReason()throws Exception{var socket=new Fake(false);socket.open();socket.awaitSend();var pool=(ThreadPoolExecutor)ReflectionTestUtils.getField(runtime,"workers");var entered=new CountDownLatch(2);var release=new CountDownLatch(1);try{for(int i=0;i<2;i++)pool.execute(()->{entered.countDown();try{release.await(3,TimeUnit.SECONDS);}catch(InterruptedException e){Thread.currentThread().interrupt();}});assertThat(entered.await(2,TimeUnit.SECONDS)).isTrue();for(int i=0;i<8;i++)pool.execute(()->{});runtime.protocol(socket.socket,1);assertThat(socket.lease.state()).isEqualTo(AlarmChangeChannelTickets.State.CLOSING);assertThat(registry.used()).isEqualTo(1);assertThat(socket.closed.getCount()).isEqualTo(1);release.countDown();socket.awaitClose();assertThat(socket.reason.get().getReasonPhrase()).isEqualTo("PROTOCOL_INVALID");}finally{release.countDown();}}
    @Test void synchronousCompletionCannotLetOldFinallyClearTheNextBlockedHeadOwner()throws Exception{
        var secondHead=new CountDownLatch(1);var releaseHead=new CountDownLatch(1);var thirdHead=new CountDownLatch(1);var firstReturning=new CountDownLatch(1);var secondSend=new CountDownLatch(1);var reads=new AtomicInteger();
        when(heads.read(anyString(),anyString())).thenAnswer(i->{int n=reads.incrementAndGet();if(n==2){secondHead.countDown();assertThat(releaseHead.await(3,TimeUnit.SECONDS)).isTrue();}if(n==3)thirdHead.countDown();return new AlarmChangeChannelHead.Head(null,0);});
        var socket=new Fake(false);var sends=new AtomicInteger();doAnswer(i->{socket.frames.add(i.getArgument(0));if(sends.incrementAndGet()==1){((SendHandler)i.getArgument(1)).onResult(new SendResult());assertThat(secondHead.await(3,TimeUnit.SECONDS)).isTrue();firstReturning.countDown();}else secondSend.countDown();return null;}).when(socket.remote).sendText(anyString(),any(SendHandler.class));
        try{socket.open();assertThat(firstReturning.await(3,TimeUnit.SECONDS)).isTrue();assertThat(thirdHead.await(200,TimeUnit.MILLISECONDS)).isFalse();releaseHead.countDown();assertThat(secondSend.await(3,TimeUnit.SECONDS)).isTrue();assertThat(reads.get()).isEqualTo(2);}finally{releaseHead.countDown();}
    }
    void manualTimer()throws Exception{var timer=(ScheduledExecutorService)ReflectionTestUtils.getField(runtime,"timer");timer.shutdownNow();assertThat(timer.awaitTermination(3,TimeUnit.SECONDS)).isTrue();}
    @SuppressWarnings("unchecked") AlarmChangeChannelRuntime.Connection connection(Fake socket){return ((Map<WebSocketSession,AlarmChangeChannelRuntime.Connection>)ReflectionTestUtils.getField(runtime,"connections")).get(socket.socket);}
    @SuppressWarnings("unchecked") AlarmChangeChannelRuntime.Connection detached(Fake socket){assertThat(registry.attach(socket.lease)).isTrue();assertThat(registry.activate(socket.lease)).isTrue();var connection=new AlarmChangeChannelRuntime.Connection(socket.socket,socket.nativeSession,socket.lease);((Map<WebSocketSession,AlarmChangeChannelRuntime.Connection>)ReflectionTestUtils.getField(runtime,"connections")).put(socket.socket,connection);return connection;}
    @Test void watchdogCannotObserveBusyBeforeDispatchHasPublishedItsStart()throws Exception{
        manualTimer();var socket=new Fake(false);var connection=detached(socket);var publishedBusy=new CountDownLatch(1);var releasePublish=new CountDownLatch(1);var sweepEntered=new CountDownLatch(1);var sweepReturned=new CountDownLatch(1);var busy=spy(new AtomicBoolean());ReflectionTestUtils.setField(connection,"busy",busy);
        doAnswer(i->{boolean changed=(boolean)i.callRealMethod();if(changed){publishedBusy.countDown();assertThat(releasePublish.await(3,TimeUnit.SECONDS)).isTrue();}return changed;}).when(busy).compareAndSet(false,true);
        try(var pool=Executors.newFixedThreadPool(2)){var writer=pool.submit(()->ReflectionTestUtils.invokeMethod(runtime,"dispatch",connection));assertThat(publishedBusy.await(3,TimeUnit.SECONDS)).isTrue();var observer=pool.submit(()->{sweepEntered.countDown();ReflectionTestUtils.invokeMethod(runtime,"sweep");sweepReturned.countDown();});try{assertThat(sweepEntered.await(3,TimeUnit.SECONDS)).isTrue();assertThat(sweepReturned.await(200,TimeUnit.MILLISECONDS)).as("watchdog must not read partially published dispatch state").isFalse();}finally{releasePublish.countDown();}writer.get(3,TimeUnit.SECONDS);observer.get(3,TimeUnit.SECONDS);assertThat(socket.closed.getCount()).isEqualTo(1);}
    }
    @Test void watchdogCannotMixNewSendingPhaseWithOldDatabaseStart()throws Exception{
        manualTimer();var socket=new Fake(false);var connection=detached(socket);connection.busy.set(true);connection.started=System.nanoTime()-TimeUnit.MILLISECONDS.toNanos(policy.sendTimeoutMs()+1);var phasePublished=new CountDownLatch(1);var releaseTransition=new CountDownLatch(1);var sweepEntered=new CountDownLatch(1);var sweepReturned=new CountDownLatch(1);
        // Exact writer-step model: suspend after writing sending but before writing its new start.
        try(var pool=Executors.newFixedThreadPool(2)){var writer=pool.submit(()->{synchronized(connection){connection.sending=true;phasePublished.countDown();try{assertThat(releaseTransition.await(3,TimeUnit.SECONDS)).isTrue();}catch(InterruptedException e){throw new AssertionError(e);}connection.started=System.nanoTime();}});assertThat(phasePublished.await(3,TimeUnit.SECONDS)).isTrue();var observer=pool.submit(()->{sweepEntered.countDown();ReflectionTestUtils.invokeMethod(runtime,"sweep");sweepReturned.countDown();});try{assertThat(sweepEntered.await(3,TimeUnit.SECONDS)).isTrue();assertThat(sweepReturned.await(200,TimeUnit.MILLISECONDS)).as("watchdog must not mix database duration with new send phase").isFalse();}finally{releaseTransition.countDown();}writer.get(3,TimeUnit.SECONDS);observer.get(3,TimeUnit.SECONDS);assertThat(socket.closed.getCount()).isEqualTo(1);}
    }
    @Test void expiredObserverCannotCloseAReplacementOperationAfterOldSendCompletes()throws Exception{
        manualTimer();var socket=new Fake(false);socket.open();socket.awaitSend();var connection=connection(socket);connection.started=System.nanoTime()-TimeUnit.MILLISECONDS.toNanos(policy.sendTimeoutMs()+1);var budgetRead=new CountDownLatch(1);var releaseDecision=new CountDownLatch(1);var nextHead=new CountDownLatch(1);var releaseHead=new CountDownLatch(1);var spiedPolicy=spy(policy);ReflectionTestUtils.setField(runtime,"policy",spiedPolicy);
        doAnswer(i->{budgetRead.countDown();assertThat(releaseDecision.await(3,TimeUnit.SECONDS)).isTrue();return i.callRealMethod();}).when(spiedPolicy).sendTimeoutMs();
        when(heads.read(anyString(),anyString())).thenAnswer(i->{nextHead.countDown();assertThat(releaseHead.await(3,TimeUnit.SECONDS)).isTrue();return new AlarmChangeChannelHead.Head(null,0);});
        try(var pool=Executors.newFixedThreadPool(2)){var observer=pool.submit(()->ReflectionTestUtils.invokeMethod(runtime,"sweep"));assertThat(budgetRead.await(3,TimeUnit.SECONDS)).isTrue();var completion=pool.submit(()->{socket.completions.getFirst().onResult(new SendResult());ReflectionTestUtils.invokeMethod(runtime,"dispatch",connection);});try{assertThat(nextHead.await(200,TimeUnit.MILLISECONDS)).as("timeout decision must fence its owner before completion can dispatch a successor").isFalse();}finally{releaseDecision.countDown();releaseHead.countDown();}observer.get(3,TimeUnit.SECONDS);completion.get(3,TimeUnit.SECONDS);socket.awaitClose();assertThat(socket.reason.get().getReasonPhrase()).isEqualTo("CHANNEL_UNAVAILABLE");assertThat(socket.frames).hasSize(1);}
    }
    @Test void nonTomcatSessionFailsClosedWithoutAnySample()throws Exception{var issue=registry.issue(AlarmChangeChannelStateTest.HASH,"tenant-a","management",AlarmChangeChannelStateTest.ORIGIN,"bootstrap-admin");var lease=registry.claim(issue.ticket(),AlarmChangeChannelStateTest.ORIGIN,"management");var socket=mock(WebSocketSession.class);when(socket.getAttributes()).thenReturn(new HashMap<>(Map.of(AlarmChangeChannelHandshake.LEASE,lease)));var closed=new CountDownLatch(1);doAnswer(i->{assertThat(((CloseStatus)i.getArgument(0)).getReason()).isEqualTo("CHANNEL_UNAVAILABLE");closed.countDown();return null;}).when(socket).close(any(CloseStatus.class));runtime.open(socket);assertThat(closed.await(3,TimeUnit.SECONDS)).isTrue();verifyNoInteractions(heads,authority);runtime.closed(socket);assertThat(registry.used()).isZero();}
}
